import type { Metadata } from "next";
import { siteConfig } from "@/lib/config";

// Generated by app/opengraph-image.tsx. Referenced explicitly: the file-based image is not inherited
// by pages under the (home) root layout.
const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "Jovens Buzz — Making Small Businesses Look Big" };

/** Metadata for a marketing page: unique title and description, canonical URL, Open Graph and Twitter cards. */
export function pageMetadata({ path, title, description }: { path: string; title: string; description: string }): Metadata {
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      url: path,
      siteName: siteConfig.name,
      title,
      description,
      locale: siteConfig.locale,
      images: [SHARE_IMAGE],
    },
    twitter: { card: "summary_large_image", title, description, images: [SHARE_IMAGE.url] },
    robots: { index: true, follow: true },
  };
}
